// Writes src/generated/index.ts: every type ts-rs generated, from one place
// (`just types` runs this after the generation).
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dir, "..", "src", "generated");
const names = readdirSync(dir)
  .filter((file) => file.endsWith(".ts") && file !== "index.ts")
  .map((file) => file.slice(0, -".ts".length))
  .sort();
const lines = [
  "// Generated by `just types` (ts-rs, then packages/edit-types/scripts/index.ts). Do not edit.",
  ...names.map((name) => `export type * from "./${name}";`),
  "",
];
writeFileSync(join(dir, "index.ts"), lines.join("\n"));
console.log(`${names.length} types in ${dir}`);
